import{_ as a}from"./chunks/rmlui.IQCB0h4b.js";import{_ as r,o as e,c as d,a2 as i}from"./chunks/framework.Ky-Ipuyb.js";const f=JSON.parse('{"title":"RmlUi ガイド","description":"","frontmatter":{"lang":"ja","sourcePath":"docs/rmlui/README.ja.md"},"headers":[],"relativePath":"ja/rmlui/index.md","filePath":"ja/rmlui/index.md"}'),l={name:"ja/rmlui/index.md"};function s(h,t,o,n,m,u){return e(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="rmlui-ガイド" tabindex="-1">RmlUi ガイド <a class="header-anchor" href="#rmlui-ガイド" aria-label="Permalink to &quot;RmlUi ガイド&quot;">​</a></h1><p><a class="library-brand" href="https://mikke89.github.io/RmlUiDoc/"><img src="'+a+`" width="246" height="84" alt="RmlUi"></a></p><p><code>sfml.js-rmlui</code> で SFML ウィンドウ内に文書ベースの UI を構築します。RML が要素ツリーを、RCSS が外観を定義し、JavaScript がアプリケーション状態とイベント処理を管理します。現在のソースは RmlUi 6.3 と SFML 3.1 を対象としています。</p><p>JavaScript と <a href="/ja/guide/window">SFML ウィンドウ</a>の基礎が前提です。RmlUi 6.3 は HTML/CSS に似ていますが、ブラウザーを組み込んでいません。<a href="/ja/rmlui/data-models">ネイティブデータモデル</a>はスカラーとコールバック、再帰レコードと配列、独自変数、共有数値領域と部分更新を扱います。以下のガイドはランタイム、文書ツリー、スタイル、描画、入力、フォント、スクリプト、リソース所有権を説明し、<a href="/ja/reference/rmlui/" target="_self">API リファレンス</a>は TypeScript の契約を示します。</p><h2 id="rmlui-とは" tabindex="-1">RmlUi とは <a class="header-anchor" href="#rmlui-とは" aria-label="Permalink to &quot;RmlUi とは&quot;">​</a></h2><p><a href="https://github.com/mikke89/RmlUi" target="_blank" rel="noreferrer">RmlUi</a> は、HTML/CSS に似た文書構文を使う C++ UI ライブラリです。RML を一度読み込むと永続的な要素ツリーを作り、RCSS で装飾し、アプリケーション状態の変化に応じて個々の要素を更新します。RmlUi がレイアウトとジオメトリの生成を行い、本パッケージが SFML で描画します。</p><p>ゲームメニュー、HUD、インベントリ、レイアウトと外観を別の素材ファイルで管理する UI に適しています。RML、RCSS、Node.js のイベント処理が連携し、ブラウザー DOM や Web の JavaScript 環境は使いません。毎フレームのウィジェット呼び出しで構築するツールには <a href="/ja/imgui/">ImGui ガイド</a>を参照してください。</p><p><a href="https://mikke89.github.io/RmlUiDoc/" target="_blank" rel="noreferrer">公式ドキュメント</a> · <a href="https://github.com/mikke89/RmlUi" target="_blank" rel="noreferrer">公式リポジトリ</a></p><h2 id="ガイド一覧" tabindex="-1">ガイド一覧 <a class="header-anchor" href="#ガイド一覧" aria-label="Permalink to &quot;ガイド一覧&quot;">​</a></h2><h3 id="入門と文書" tabindex="-1">入門と文書 <a class="header-anchor" href="#入門と文書" aria-label="Permalink to &quot;入門と文書&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章</th><th>内容</th></tr></thead><tbody><tr><td><a href="/ja/rmlui/getting-started">クイックスタート</a></td><td>カウンターを実行し、初期化、フォント、フレーム順序を理解</td></tr><tr><td><a href="/ja/rmlui/rml-rcss">RML と RCSS の基礎</a></td><td>マークアップ、セレクター、レイアウト、クリック処理、公式構文リファレンス</td></tr><tr><td><a href="/ja/rmlui/documents">文書とイベント</a></td><td>RML の読み込み、要素編集、リスナー登録、ネイティブオブジェクトの解放</td></tr><tr><td><a href="/ja/rmlui/streams">バイトストリーム</a></td><td>ファイル、メモリ、コールバックストリームの読み込みと有効期間</td></tr><tr><td><a href="/ja/rmlui/strings">文字列とリソース URL</a></td><td>文字列処理、リソースパスと URL</td></tr></tbody></table><h3 id="要素、レイアウトとコントロール" tabindex="-1">要素、レイアウトとコントロール <a class="header-anchor" href="#要素、レイアウトとコントロール" aria-label="Permalink to &quot;要素、レイアウトとコントロール&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章</th><th>内容</th></tr></thead><tbody><tr><td><a href="/ja/rmlui/element-state">要素のクラス、属性とフォーカス</a></td><td>要素の状態、クラスとフォーカスを変更</td></tr><tr><td><a href="/ja/rmlui/element-utilities">要素ユーティリティ</a></td><td>位置指定、テキスト測定、投影境界とクリップジオメトリ</td></tr><tr><td><a href="/ja/rmlui/layout">レイアウト、スクロールと投影</a></td><td>レイアウト寸法、スクロール位置と座標投影</td></tr><tr><td><a href="/ja/rmlui/boxes">ボックスと描画ボックス</a></td><td>ボックスモデルの値と描画ボックス</td></tr><tr><td><a href="/ja/rmlui/controls">フォームコントロール</a></td><td>入力、選択コントロールとフォーム操作</td></tr><tr><td><a href="/ja/rmlui/text-panels">テキスト、進捗バーとタブ</a></td><td>テキスト要素、進捗表示とタブ</td></tr><tr><td><a href="/ja/rmlui/vector-elements">SVG と Lottie</a></td><td>Native ベクター要素、デコレーター、フレームとソース</td></tr><tr><td><a href="/ja/rmlui/rtti-default-actions">ネイティブ型と既定の動作</a></td><td>要素型の識別と既定のイベント動作</td></tr></tbody></table><h3 id="スタイル、アニメーションと描画" tabindex="-1">スタイル、アニメーションと描画 <a class="header-anchor" href="#スタイル、アニメーションと描画" aria-label="Permalink to &quot;スタイル、アニメーションと描画&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章</th><th>内容</th></tr></thead><tbody><tr><td><a href="/ja/rmlui/numeric-values">数値と単位</a></td><td>型付き数値、単位と変換</td></tr><tr><td><a href="/ja/rmlui/properties">型付きプロパティ</a></td><td>プロパティの定義、解析と型付き値</td></tr><tr><td><a href="/ja/rmlui/animation">アニメーションとイージング</a></td><td>要素アニメーション、キーフレームとイージング</td></tr><tr><td><a href="/ja/rmlui/geometry-utilities">ジオメトリと畳み込み</a></td><td>メッシュの一括生成と共有アルファ領域のフィルター</td></tr><tr><td><a href="/ja/rmlui/resources">描画リソース</a></td><td>テクスチャ、シェーダー、フィルターと Factory リソース</td></tr><tr><td><a href="/ja/rmlui/render-state">描画状態</a></td><td>クリップ、レイヤー、コールバックテクスチャと状態復元</td></tr><tr><td><a href="/ja/rmlui/rendering">描画と Retina</a></td><td>SFML との合成、高密度表示、エフェクトの対応範囲</td></tr></tbody></table><h3 id="ランタイムと拡張" tabindex="-1">ランタイムと拡張 <a class="header-anchor" href="#ランタイムと拡張" aria-label="Permalink to &quot;ランタイムと拡張&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章</th><th>内容</th></tr></thead><tbody><tr><td><a href="/ja/rmlui/plugins">プラグイン</a></td><td>プラグイン登録とランタイムコールバック</td></tr><tr><td><a href="/ja/rmlui/scripts">文書スクリプト</a></td><td>Node.js と Lua の文書スクリプト</td></tr><tr><td><a href="/ja/rmlui/data-models">ネイティブデータモデル</a></td><td>バインディング、式、共有配列と部分更新</td></tr><tr><td><a href="/ja/rmlui/fonts">フォント</a></td><td>フォントエンジン、シェーピングとグリフアトラス</td></tr><tr><td><a href="/ja/rmlui/debugger">ネイティブ Debugger</a></td><td>別ホストで要素、ログ、データモデルを検査</td></tr><tr><td><a href="/ja/rmlui/performance">共有領域とバッチ処理</a></td><td>数値コマンド、まとめた JS 計算、リソースの準備</td></tr><tr><td><a href="/ja/rmlui/source-layout">ソース構成</a></td><td>Native バインディング、TypeScript インターフェースとツール</td></tr><tr><td><a href="/ja/rmlui/api">API ガイド</a></td><td>型、既定値、戻り値、有効期間の契約</td></tr></tbody></table><p>ガイドとソースから生成する API リファレンスは、英語、簡体字中国語、日本語、韓国語で保守しています。</p><h2 id="サンプルを実行" tabindex="-1">サンプルを実行 <a class="header-anchor" href="#サンプルを実行" aria-label="Permalink to &quot;サンプルを実行&quot;">​</a></h2><p>monorepo のルートで実行します。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/bootstrap.cjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js-rmlui/examples/demo.cjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js-rmlui/examples/official.cjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> variables</span></span></code></pre></div><p><a href="/ja/examples/rmlui">サンプル一覧</a>に画面、操作方法、ソースリンクがあります。カウンターの Increment は動作しますが、variables のミッションボタンはホバースタイルのみです。</p><h2 id="所有権の境界" tabindex="-1">所有権の境界 <a class="header-anchor" href="#所有権の境界" aria-label="Permalink to &quot;所有権の境界&quot;">​</a></h2><p>プロセス全体のランタイムは 1 つの <code>RenderWindow</code> に接続し、初期化した Node.js 環境とスレッドに属します。コンテキスト、文書、フォント、描画リソースを管理します。ラッパーはネイティブの有効性を共有します。JS 参照は所有権付き未接続ツリーを保持し、接続済み要素の寿命は親が管理します。破棄時にリスナーを自動解放し、無効なラッパーの使用は例外になります。SFML ウィンドウを閉じる前に RmlUi を終了してください。遅延破棄と Worker の制約は<a href="/ja/rmlui/documents#ネイティブの有効期間">ネイティブの有効期間</a>を参照してください。</p>`,24)])])}const b=r(l,[["render",s]]);export{f as __pageData,b as default};
